// Search configuration, versioned with this workflow (mirrors the As-Is config.json).
const config = {
  daysBack: 21,
  pages: 2,
  perPage: 50,
  // Optional sources (Chiletrabajos) are enabled in matcher via MATCHER_ENABLED_SOURCES (ADR-0008).
  optionalMaxDetails: 60,
  categories: ['hardware-electronics', 'machine-learning-ai'],
  queries: [
    'ingeniero electronico', 'ingeniero civil electronico', 'ingeniero electrico',
    'ingeniero automatizacion', 'ingeniero control', 'instrumentacion', 'telecomunicaciones',
    'sistemas embebidos', 'hardware', 'plc scada', 'iot', 'ai engineer',
    'inteligencia artificial', 'machine learning', 'vision artificial',
  ],
};
return [{ json: { config } }];

// Scheduled ticks run only if today's ingestion has not succeeded yet, none is in progress and fewer
// than 3 attempts failed today. CLI and editor runs always proceed. An unknown mode is treated as
// scheduled, so a change in n8n internals can never turn the hourly ticks into hourly ingestions.
const { mode, ran_today, running, failed_today } = $('Gate').first().json;
const scheduled = mode !== 'cli' && mode !== 'manual';
if (scheduled && (ran_today || running || failed_today >= 3)) {
  return [];  // nothing to do this hour; the workflow ends here
}
return [{ json: { trigger: scheduled ? 'schedule' : 'manual', mode } }];

