// One GET per (category or query) x page. Get on Board public API v0 (ADR-0003).
const { config } = $('Config').first().json;
const base = 'https://www.getonbrd.com/api/v0';
const expand = encodeURIComponent(JSON.stringify(['company', 'seniority', 'location_cities', 'modality']));
const targets = [
  ...config.categories.map((c) => ({ label: `category:${c}`, path: `/categories/${c}/jobs?` })),
  ...config.queries.map((q) => ({ label: `query:${q}`, path: `/search/jobs?query=${encodeURIComponent(q)}&` })),
];
const out = [];
for (const t of targets) {
  for (let page = 1; page <= config.pages; page++) {
    out.push({ json: { label: t.label, page, url: `${base}${t.path}per_page=${config.perPage}&page=${page}&expand=${expand}` } });
  }
}
return out;

// Flatten API pages, keep recent jobs, de-duplicate ids within the run, count errors.
const { config } = $('Config').first().json;
const cutoff = Date.now() / 1000 - config.daysBack * 86400;
const seen = new Set();
const items = [];
let fetched = 0, errors = 0, errorSample = null;
for (const response of $input.all()) {
  if (response.json.error) {
    errors++;
    errorSample ??= String(response.json.error.message ?? JSON.stringify(response.json.error)).slice(0, 300);
    continue;
  }
  for (const job of response.json.data ?? []) {
    fetched++;
    if ((job.attributes?.published_at ?? 0) < cutoff || seen.has(job.id)) continue;
    seen.add(job.id);
    items.push(job);
  }
}
// USD->CLP: mindicador.cl (Banco Central series), else open.er-api.com, else null (salary kept as USD note).
return [{ json: { source: 'getonbrd', items, fetched, errors, error_sample: errorSample } }];

// One item per source batch: Get on Board (fetched by n8n) + enabled optional sources (fetched by matcher).
// USD->CLP: mindicador.cl (Banco Central series), else open.er-api.com, else null (salary kept as USD note).
const usd = $('USD rate').first().json?.serie?.[0]?.valor
  ?? $('USD rate (fallback)').first().json?.rates?.CLP
  ?? null;
const batches = [$('Collect Get on Board').first().json];
// A failed call to matcher is recorded by "Combine" as source 'optional-sources'; it has nothing to normalise.
for (const b of $('Optional sources').first().json.batches ?? []) {
  batches.push({ source: b.source, items: b.items, fetched: b.listed, errors: b.errors, error_sample: b.error_sample });
}
return batches.map((b) => ({ json: { ...b, usd_clp: usd } }));

// Merge normalised offers from every batch; per-source stats for the run log.
const batches = $('Batches').all().map((i) => i.json);
const normalized = $input.all().map((i) => i.json);
const offers = [];
const stats = batches.map((b, idx) => {
  const n = normalized[idx] ?? {};
  offers.push(...(n.offers ?? []));
  const rejected = (n.rejected ?? []).length;
  return { source: b.source, fetched: b.fetched, errors: b.errors + rejected + (n.error ? 1 : 0),
           error_sample: b.error_sample ?? (rejected ? `rejected: ${n.rejected[0].reason}` : null) ?? '' };
});
const optionalError = $('Optional sources').first().json.error;
if (optionalError) {
  stats.push({ source: 'optional-sources', fetched: 0, errors: 1,
               error_sample: String(optionalError.message ?? 'optional sources failed').slice(0, 300) });
}
return [{ json: { offers, stats } }];
